import type{ReactNode}from'react';import{F2DeepDive,f2Quiz}from'./fashionM2Core';import type{FashionM2Question,FashionM2Source,FashionM2Takeaways}from'./fashionM2Core';import{VisualView}from'./fashionVisualKit';import type{VisualSpec}from'./fashionVisualKit';import{DEVELOPMENT_CHAPTER_VISUALS}from'./realEstateDevelopmentVisualSpecs';export const RE_DEVELOPMENT_SOURCES={worldBankUrban:{title:'Vietnam’s Urbanization at a Crossroads',href:'https://documents.worldbank.org/pt/publication/documents-reports/documentdetail/295641604685477960',publisher:'World Bank',note:'Urbanization, land, housing and infrastructure context; historical observations and recommendations are not current property forecasts.'},unHabitatLand:{title:'Sustaining Urban Land Information',href:'https://unhabitat.org/sustaining-urban-land-information',publisher:'UN-Habitat',note:'Normative guidance on land administration, ownership, value, transfer, planning and development-potential information.'},unHabitatPlanning:{title:'Urban Planning and Sustainable Infrastructure — Resolution 2/8',href:'https://unhabitat.org/sites/default/files/2023/09/resolution_2-8-_urban_planning_and_instrastructure_-_hsp-ha.2-res.8_-_advance_-_1.09.23.pdf',publisher:'UN-Habitat Assembly (2023)',note:'Global planning and infrastructure framework; implementation varies by national and local law.'},imfCre:{title:'Financial Stability Risks from Commercial Real Estate',href:'https://www.elibrary.imf.org/view/journals/002/2024/230/article-A002-en.xml',publisher:'International Monetary Fund (2024)',note:'Evidence on financing, valuation and commercial-property risk in studied markets; results are not universal asset forecasts.'},moc2025:{title:'Vietnam Real Estate Market Developments 2025',href:'https://kinhtexaydung.gov.vn/thong-tin-cong-bo/bao-cao-dien-bien-thi-truong-bat-dong-san-nam-2025/',publisher:'Institute of Construction Economics — Vietnam Ministry of Construction',note:'Official market report covering housing and real-estate developments; segment, location, period and data basis matter.'},mocDisclosure:{title:'Vietnam Housing and Real Estate Market Information — Q2 2025',href:'https://moc.gov.vn/vn/_layouts/15/NCS.Webpart.MOC/mt_poup/Intrangweb.aspx?IdNews=87076',publisher:'Vietnam Ministry of Construction',note:'Official quarterly disclosure context; project counts, transactions, prices and inventory are different measures.'},ifcGreen:{title:'Green Buildings',href:'https://www.ifc.org/en/what-we-do/sector-expertise/climate-business/promoting-sustainable-innovation/green-buildings',publisher:'International Finance Corporation',note:'Green-building framework and EDGE context; modeled resource savings depend on project baseline, design and verification.'},ifcVietnam:{title:'Vietnam Green Building Promotion',href:'https://disclosures.ifc.org/project-detail/AS/602195/vn-gb-promotion',publisher:'International Finance Corporation',note:'Vietnam building energy-efficiency and certification program context; legal applicability must be checked against current official rules.'}} satisfies Record<string,FashionM2Source>;export type ReDevelopmentSourceId=keyof typeof RE_DEVELOPMENT_SOURCES;export type ReDevelopmentVisualKind=`realestate-development-m${number}-${number}`;export interface ReDevelopmentCardData{title:string;chapterTitle:string;readingTime:string;legacyIndex?:number;legacyIndexes?:number[];legacyCompletionIndex?:number;migrationVersion?:string;objective:string;mateIntro:string;keyInsight:string;concepts:[];narrative:Array<{label:'What it is'|'Why it is happening'|'Real-world example'|'Vietnam example'|'Business impact';text:string}>;visualKind:ReDevelopmentVisualKind;visualHeading:string;visualIntro:string;imageAlt:string;statTiles:Array<{value?:string;label:string;subtitle?:string;description:string}>;statsNote:string;keyTerms:Array<{term:string;definition:string}>;recap:string[];chapterRecap:string;deepDiveTitle:string;body:ReactNode;sources:FashionM2Source[]}export type DevelopmentStat={value?:string;label:string;subtitle?:string;description:string};export type DevelopmentItem={title:string;dimensions:string[];insight:string;scope:string;example:string;vietnam:string;sources:ReDevelopmentSourceId[];stats?:DevelopmentStat[];legacyIndex?:number;legacyIndexes?:number[];legacyCompletionIndex?:number};export type DevelopmentLesson=[string,DevelopmentItem[]];
const DEVELOPMENT_M1_TITLES:Record<string,string[]>={'Industry Definition & Scope':['What Is Property Development & Investment?','What Makes Property Development Unique?','Where Does the Industry Begin and End?','Understanding Major Property and Investment Models',"Who Are the Industry's Customers and Stakeholders?"],'Industry History & Development':['How Did Modern Property Development Evolve?','How Did Urbanization and Infrastructure Shape Development?','How Did Institutional Property Investment Develop?',"How Has Vietnam's Property Industry Developed?"],'Global Market Overview':['How Is the Global Property Industry Structured?','How Are Property Markets Measured?','Which Asset Classes and Regions Drive Activity?','Who Are the Major Global Participant Types?','How Do Capital Markets and Property Cycles Interact?'],'Vietnam Market Overview':["What Does Vietnam's Property Market Look Like?",'How Do Residential, Commercial and Industrial Segments Differ?','How Do Developers, Investors and Lenders Participate?','How Do Supply, Demand, Sales and Leasing Interact?','How Do Legal Readiness and Financing Shape Vietnam Projects?'],'Industry Drivers & External Factors':['How Do Demographics and Economic Activity Drive Demand?','How Does Infrastructure Affect Property Feasibility?','How Do Interest Rates, Credit and Construction Costs Matter?','How Do Planning and Regulatory Processes Shape Projects?','How Do Climate, Sustainability and Liquidity Risks Matter?']};
const DEVELOPMENT_M1_TARGETS:Record<string,number[]>={'Industry Definition & Scope':[0,2],'Industry History & Development':[0,2],'Global Market Overview':[0,3],'Vietnam Market Overview':[0,4],'Industry Drivers & External Factors':[0,4]};
const DEVELOPMENT_DETAILS:Record<string,Partial<DevelopmentItem>>={'Where Does the Industry Begin and End?':{dimensions:['Landowner','Developer','Investor','Contractor','Broker','Asset manager','Occupier'],scope:'Developers assemble rights, approvals, capital and delivery; contractors build; brokers transact; investors provide or own capital; asset managers operate and improve completed assets.',insight:'Property development, construction contracting, brokerage, investment and asset management are connected but distinct businesses.',example:'A developer can appoint a contractor and broker, sell apartments, and retain a retail podium under asset management.',vietnam:'Define legal entity, rights, project stage, contract, revenue model and risk ownership.'},'Understanding Major Property and Investment Models':{dimensions:['Residential sale','Commercial lease','Industrial lease','Develop-to-sell','Develop-to-hold','Joint venture','Repositioning'],scope:'Residential, office, retail, industrial, logistics and mixed-use assets have different customers, revenue timing, capital needs and operating intensity.',insight:'Project sales and recurring rental income require different feasibility, finance and risk frameworks.',example:'A condominium can monetize through presales and handover while a logistics asset depends on lease-up and recurring NOI.',vietnam:'Compare only aligned property type, location, lifecycle and capital structure.'},'How Are Property Markets Measured?':{dimensions:['GFA','NSA','NLA','GDV','Pipeline','Approval','Completion','Transaction','Absorption','Occupancy','Revenue','Cash'],scope:'Area, pipeline, approvals, completions, transactions, sales, leasing, revenue and cash measure different stages and entities.',insight:'Announced pipeline is not approved supply; approved supply is not completion; sales are not necessarily cash or profit.',example:'A 100,000 m² GFA project may have lower saleable or leasable area after common, service and circulation space.',vietnam:'State asset, location, unit, period, stage and reporting basis.'},'How Do Residential, Commercial and Industrial Segments Differ?':{dimensions:['Residential','Office','Retail','Industrial park','Logistics','Hospitality'],scope:'Asset classes differ in buyers or tenants, lease structure, infrastructure, operating requirements, cycle and valuation.',insight:'A housing project, office tower and industrial park should not share one demand or cash-flow model.',example:'Residential absorption tracks unit sales while an office emphasizes NLA, rent, occupancy and tenant retention.',vietnam:'Use segment- and location-specific official evidence.'},'How Do Legal Readiness and Financing Shape Vietnam Projects?':{dimensions:['Land-use right','Planning','Investment approval','Construction','Sale or lease readiness','Debt','Equity'],scope:'Feasibility depends on verified rights, current approvals, lawful commercialization, capital availability and timing.',insight:'A good site is not investable when rights, approvals, funding or sale and lease conditions are unresolved.',example:'Approval delay can extend interest carry before presales or leasing begin.',vietnam:'Verify current primary law and project-specific facts with qualified professionals; unresolved claims remain Verification Required — Do Not Publish.'}};
function standardizeDevelopmentLessons(module:number,lessons:DevelopmentLesson[]):DevelopmentLesson[]{if(module!==1)return lessons;return lessons.map(([lesson,items])=>{const titles=DEVELOPMENT_M1_TITLES[lesson]??items.map(item=>item.title);const targets=DEVELOPMENT_M1_TARGETS[lesson]??items.map((_,i)=>i);return[lesson,titles.map((title,index)=>{const legacyIndexes=targets.flatMap((target,legacyIndex)=>target===index?[legacyIndex]:[]);let sourceIndex=0,distance=Infinity;targets.forEach((target,i)=>{const d=Math.abs(target-index);if(d<distance){distance=d;sourceIndex=i}});const base=items[sourceIndex];const detail=DEVELOPMENT_DETAILS[title];return{...base,title,dimensions:detail?.dimensions??[base.dimensions[index%base.dimensions.length]],scope:detail?.scope??`${title} focuses on ${base.scope}`,insight:detail?.insight??`${base.insight} This chapter isolates ${title.toLowerCase()}.`,example:detail?.example??base.example,vietnam:detail?.vietnam??base.vietnam,legacyIndex:legacyIndexes[0],legacyIndexes,legacyCompletionIndex:legacyIndexes[0]}})]})}
export function buildDevelopmentLegacyManifest(lessons:DevelopmentLesson[]){return standardizeDevelopmentLessons(1,lessons).flatMap(([lesson,items],lessonIndex)=>items.flatMap((item,successorIndex)=>(item.legacyIndexes??[]).map(legacyIndex=>({module:1,lesson,lessonIndex,legacyIndex,legacyTitle:lessons[lessonIndex][1][legacyIndex]?.title??'',successorIndex,successorTitle:item.title,migrationVersion:'realestate-development-full-v1'}))))}
const definitions:Record<string,string>={'Development feasibility':'Evidence-based assessment of rights, planning, demand, design, cost, finance, schedule and return.','Land due diligence':'Review of ownership or use rights, planning, encumbrances, access, obligations and development constraints.','Capital structure':'The mix and terms of equity, debt and other funding used by a project or asset.','Net operating income':'Property operating revenue less defined operating expenses before financing and certain other items.','Occupancy':'Leased or occupied space relative to available space under a stated basis and date.','Absorption':'Sales or leasing achieved relative to available supply during a defined period.','Exit value':'Expected or realized value when an investment or project interest is sold.','Asset management':'Active management of leasing, income, costs, capital works, risk and strategy to improve asset outcomes.','Mixed-use development':'A coordinated project combining multiple uses such as residential, office, retail or hospitality.','Transit-oriented development':'Compact mixed-use development planned around accessible public transport.','Gross development value':'Estimated aggregate value of completed saleable units or interests under stated price and timing assumptions.','Gross floor area':'Total floor area under the applicable measurement convention.','Net saleable area':'Area available for sale under a defined measurement basis.','Net leasable area':'Area available to lease under a defined measurement basis.','Loan to cost':'Debt divided by defined total development cost.','Loan to value':'Debt divided by defined property or collateral value.','Debt service coverage ratio':'Defined income or cash available for debt service divided by scheduled debt service.','Project IRR':'Discount rate that sets project-level unlevered cash-flow NPV to zero.','Equity IRR':'Discount rate that sets equity investor cash-flow NPV to zero after financing flows.'};const terms=(a:string[])=>a.slice(0,5).map(term=>({term,definition:definitions[term]??`A core Property Development and Investment concept related to ${term.toLowerCase()}.`}));function chapter(module:number,lesson:string,item:DevelopmentItem,index:number):ReDevelopmentCardData{const visual=DEVELOPMENT_CHAPTER_VISUALS[`realestate-development-m${module}-${index}`];const impact=`For decision-makers, ${item.insight.toLowerCase()} Define property type, location, rights, lifecycle stage, customer, capital structure, timing and evidence before acting.`;const recap=[item.insight,impact,`Key dimensions include ${item.dimensions.join(', ')}.`];return{title:`${String(index).padStart(2,'0')} ${item.title}`,chapterTitle:lesson,readingTime:'8',legacyIndex:item.legacyIndex,legacyIndexes:item.legacyIndexes,legacyCompletionIndex:item.legacyCompletionIndex,migrationVersion:'realestate-development-full-v1',objective:`Explain ${item.title.toLowerCase()} and apply it to an evidence-based property decision.`,mateIntro:`This chapter examines ${item.scope}`,keyInsight:item.insight,concepts:[],narrative:[{label:'What it is',text:item.scope},{label:'Why it is happening',text:`Urbanization, infrastructure, capital markets, customer needs, regulation and climate risk are increasing the importance of this topic. ${item.insight}`},{label:'Real-world example',text:item.example},{label:'Vietnam example',text:item.vietnam},{label:'Business impact',text:impact}],visualKind:`realestate-development-m${module}-${index}`as ReDevelopmentVisualKind,visualHeading:visual?.heading??item.title,visualIntro:visual?.intro??'The factors this chapter connects. They are considered together, not as sequential stages.',imageAlt:`Casemate Property Development and Investment visual for ${item.title}`,statTiles:item.stats??[{value:String(item.dimensions.length),label:'Decision dimensions',description:item.dimensions.join(' · ')},{value:String(item.sources.length),label:'Evidence sources',description:'Official, institutional, or clearly scoped analytical evidence.'},{value:'1',label:'Central insight',description:item.insight}],statsNote:item.stats?'Figures retain property type, location, source, period, metric and estimate, observation, forecast or target status.':'Tiles summarize the framework; pipeline, approvals, units, transactions, prices, revenue, cash, asset value and profit are not combined.',keyTerms:terms(item.dimensions),recap,chapterRecap:recap.join(' '),deepDiveTitle:'How land, capital and execution create property value—and where timing, leverage and demand can destroy it',body:<F2DeepDive paragraphs={[item.scope,item.insight,item.example,item.vietnam,impact]} evidence="Property type, rights, approvals, pipeline, completion, sales, occupancy, income, valuation, cash and profit remain distinct measures."/>,sources:item.sources.map(id=>RE_DEVELOPMENT_SOURCES[id])}}function seed(chapter:string,q:string,a:string,c:string){return{chapter,objective:q,question:q,application:a,correct:c,wrong:['Assume property prices will rise instead of testing project cash flows','Treat announced pipeline, transaction value or appraisal as realized profit','Acquire land without rights, planning, demand, finance and exit evidence']as[string,string,string],explanation:'Property decisions require defined asset, location, rights, lifecycle stage, demand, capital, schedule, cash flow, controls and evidence.'}}function calculationSeed(chapter:string,question:string,application:string,correct:string,wrong:[string,string,string]){return{chapter,objective:question,question,application,correct,wrong,explanation:'Use only the stated project, timing, area, value, cost and financing assumptions. HYPOTHETICAL figures are not market or company data.'}}
function extraSeed(chapter:string,question:string,application:string,correct:string,wrong:[string,string,string],explanation:string){return{chapter,objective:question,question,application,correct,wrong,explanation}}
const EXTRA_SEEDS:Record<string,ReturnType<typeof extraSeed>[]>={'realestate-development-m2-l1':[extraSeed('1','Why should a project not advance merely because land is available?','A team controls a site and wants to start design immediately, before feasibility and approvals are tested. What does the chapter recommend?','Use stage gates tied to verified evidence, because value is created through gated decisions across the lifecycle',['Start design at once, because land control proves the project is viable','Skip feasibility, because approvals and finance can be arranged after construction starts','Treat land availability as the final gate before sales launch'],'Value is created through gated decisions across a long, capital-intensive lifecycle. A project should not advance merely because land is available, so use stage gates tied to verified evidence.'),extraSeed('2','Which risk does a construction contractor not necessarily carry on a development project?','A developer assumes the main contractor will share the loss if units sell slowly. Which statement is accurate?','Market absorption risk, because the contractor bears delivery obligations rather than sales risk',['Delivery risk, because contractors carry no obligation for the works','All project risks, because the contractor is paid first','Planning risk only, because contractors also own the land'],'Contracts allocate control, return and risk among specialized participants. A contractor bears delivery obligations but not necessarily market absorption risk, so map entity, contract and project stage.')],'realestate-development-m2-l3':[extraSeed('1','How can a project with a healthy static margin still run into funding trouble?','A feasibility study shows a strong profit margin, but costs fall due long before sales cash arrives. What does the chapter warn?','A profitable static margin can still face negative interim cash, so timing and contingencies must be modelled',['A healthy margin guarantees positive cash at every stage','Interim cash shortfalls only arise when the margin is negative','Timing affects accounting profit but never funding needs'],'Feasibility integrates legal, market, design, cost, finance and schedule assumptions. A profitable static margin can still face negative interim cash, so model timing and contingencies explicitly.'),extraSeed('3','What can unapproved construction variations do to a project?','Site teams issue several scope changes without formal approval. What risk does the chapter flag?','They can consume contingency and delay loan drawdown, so cost-to-complete and funding headroom must be tracked',['They reduce cost because work moves faster','They have no effect on financing because lenders ignore scope','They only affect the design team and not the budget'],'Capital and delivery controls must remain aligned with scope and schedule. Unapproved variations can consume contingency and delay drawdown, so track cost-to-complete and funding headroom.')],'realestate-development-m2-l4':[extraSeed('1','Are residential bookings the same as recognized revenue or cash?','A sales team reports a record number of bookings at launch. How should finance treat that figure?','No: reservations, contracts, collections and handovers must be tracked separately',['Yes: every booking is recognized revenue on the day it is made','Yes: bookings equal cash because deposits are always collected in full','No: bookings have no value and should not be reported'],'Residential commercialization converts product into contracted sales and cash over time. Bookings are not automatically recognized revenue or cash, so separate reservations, contracts, collections and handovers.'),extraSeed('2','Why can headline rent overstate the income of a leased building?','A landlord advertises a high asking rent but grants long rent-free periods and fit-out contributions. What should an investor examine?','Effective rent after incentives, with the rent, occupancy and expense basis defined',['Headline rent alone, because incentives do not affect income','Occupancy alone, because rent levels do not affect NOI','Gross floor area alone, because it determines income'],'Income property value depends on durable occupancy and operating performance. Headline rent can differ from effective rent after incentives, so define rent, occupancy and expense basis.')],'realestate-development-m2-l5':[extraSeed('1','How does project delay affect development economics?','An approval takes a year longer than planned while land and early costs are already funded. What does the chapter highlight?','Delay increases financing and opportunity cost, so committed and forecast cost must be tracked',['Delay has no cost because land values always rise','Delay only affects the contractor and not the developer','Delay reduces cost because spending is postponed'],'Property development combines scarce rights, finance and delivery capability. Delay increases financing and opportunity cost, so track committed and forecast cost.'),extraSeed('2','Why can gross floor area not be used directly as sellable or lettable area?','A pricing model multiplies the full GFA by the sale price per square metre. What is the error?','GFA does not equal NSA or NLA, so the measurement standard and date must be recorded',['There is no error, because GFA and NSA are always identical','The error is only in the sale price, not the area','GFA should always be smaller than NSA'],'Outputs need consistent measurement conventions and acceptance rules. GFA does not equal NSA or NLA, so record the measurement standard and date.')],'realestate-development-m2-l6':[extraSeed('2','Can strong buyer demand in Vietnam make up for legal or funding gaps?','A project in a popular district has high buyer interest but unresolved approvals and incomplete financing. Which statement is accurate?','No: strong demand does not cure legal or funding gaps, so current official disclosures should be used',['Yes: high demand guarantees that approvals will follow','Yes: buyer deposits replace the need for project finance','No: demand is irrelevant to project feasibility'],'Vietnam projects operate through local rights, approval, finance and channel structures. Strong demand does not cure legal or funding gaps, so use current official disclosures.'),extraSeed('3','When does an announced road interchange add value to a site?','A land seller prices a plot on the basis of a planned interchange nearby. What should the buyer test?','Whether delivery and access are credible, by stress-testing timing and dependency',['Nothing, because announced infrastructure always adds value immediately','Only the land price of the nearest competitor','Only the number of lanes in the planned road'],'Local feasibility depends on infrastructure delivery and market depth. An announced interchange matters only if delivery and access are credible, so stress-test timing and dependency.')],'realestate-development-m3-l1':[extraSeed('1','What can a static profit figure hide in a develop-to-sell project?','A merchant developer shows strong total profit, but construction spending peaks long before handover collections. What does the chapter warn?','Cash-flow pressure before handover, so collection milestones and legal readiness must be modelled',['Nothing, because static profit already reflects cash timing','Only tax effects, because cash timing is irrelevant to merchant development','Rental income risk, because develop-to-sell projects depend on leases'],'Merchant development monetizes completed units or projects and depends on absorption and delivery. Static profit can hide cash-flow pressure before handover, so model collection milestones and legal readiness.'),extraSeed('3','Why must joint venture terms be documented carefully?','A landowner contributes a site and a fund contributes equity to a joint venture. What does the chapter highlight?','The partners may have different priorities, so approvals, reserved matters and exit should be documented',['Partners always share identical priorities, so documentation is optional','The fund automatically controls every decision','The landowner bears no risk once the land is contributed'],'Partnership structures combine resources but require clear control and waterfall terms. A land-contribution partner and equity investor may have different priorities, so document approvals, reserved matters and exit.')],'realestate-development-m3-l2':[extraSeed('1','Why should residential sales velocity be tracked by unit type?','Two-bedroom units sell out while three-bedroom units in the same tower sell slowly. What does the chapter suggest?','Sales velocity can differ by unit type within one project, so segment by city, price and buyer need',['Sales velocity is identical for all unit types in a project','Only the overall project sales rate matters','Unit type affects price but never sales pace'],'Residential products are shaped by household demand, affordability and delivery trust. Sales velocity can differ by unit type within one project, so segment by city, price and buyer need.'),extraSeed('2','What trade-off does a mixed-use development carry?','A developer combines offices, retail and a hotel in one scheme to spread demand risk. What does the chapter caution?','Mixed use can diversify demand but adds interface complexity, so each component should be modelled separately',['Mixed use removes all demand risk','Mixed use always lowers operating cost','All components should share one blended demand model'],'Commercial assets depend on occupier economics and operating quality. Mixed use can diversify demand but adds interface complexity, so model each component separately.')],'realestate-development-m3-l3':[extraSeed('1','Does strong investor presale demand prove end-user demand?','Most early buyers in a project are investors planning to resell. Which statement is accurate?','No: an investor presale is not proof of end-user demand, so buyer type and funding should be separated',['Yes: every presale reflects owner-occupier demand','Yes: investor buyers guarantee future occupancy','No: investor buyers should never be counted as sales'],'Residential customers need credible legal status, product quality and payment fit. An investor presale is not proof of end-user demand, so separate buyer type and funding.'),extraSeed('3','How may a lender respond when cost-to-complete rises on a project?','Construction cost forecasts climb well above the original budget mid-project. What does the chapter say lenders may do?','Restrict drawdown, so reporting should be aligned with financing terms',['Increase the loan automatically without conditions','Ignore cost forecasts until handover','Convert the loan into equity at no cost'],'Investors and lenders prioritize risk-adjusted cash flows and control. Lenders may restrict drawdown when cost-to-complete rises, so align reporting with financing terms.')],'realestate-development-m3-l5':[extraSeed('1','Why is a reservation count not a measure of sales or cash?','A showroom reports hundreds of reservations at launch. How should management read the number?','Reservations are not contracted sales or collected cash, so funnel stages must be used consistently',['Reservations equal signed contracts','Reservations equal cash in the bank','Reservations cannot inform sales planning at all'],'Direct residential sales coordinate product, pricing, documentation and collections. Reservation count is not contracted sale or collected cash, so use funnel stages consistently.'),extraSeed('2','What can duplicate leads cause in a broker network?','Two agencies claim the same buyer and both demand commission. What does the chapter advise?','Commission disputes, so authorization and claim rules should be defined in advance',['Nothing, because both agencies are always paid','Higher sales, because duplicate leads double demand','Lower prices, because buyers negotiate with two brokers'],'Broker networks expand reach but need governance and attribution. Duplicate leads can create commission disputes, so define authorization and claim rules.')],'realestate-development-m3-l6':[extraSeed('2','How can value engineering reduce the lifecycle value of an asset?','To cut construction cost, a team downgrades building systems that will be costly to operate. What does the chapter warn?','Value engineering that harms operations can reduce lifecycle value, so change and quality governance is needed',['Any construction saving always increases asset value','Operating cost is irrelevant once the building is handed over','Value engineering affects only the design fee'],'Technical teams convert concept into compliant, operable assets. Value engineering that harms operations can reduce lifecycle value, so use change and quality governance.'),extraSeed('3','How should a developer treat customer deposits?','A developer plans to use buyer deposits as if they were its own equity in the project. Which statement is accurate?','Customer deposits create obligations, not free equity',['Deposits are free equity with no obligations attached','Deposits replace the need for lender approval','Deposits belong to the contractor once paid'],'Property outcomes affect and depend on many capital and user stakeholders. Customer deposits create obligations, not free equity, so communicate evidence and constraints.')],'realestate-development-m4-l1':[extraSeed('1','Does a strong national brand protect a developer from local competition?','A well-known developer launches in a district with several competing projects. What does the chapter suggest?','No: a strong brand can still face intense project-level rivalry, so each segment and micro-market should be assessed',['Yes: national brands always win local competition','Yes: brand strength removes the need for local research','No: brands have no effect on buyer choice'],'Competition is local, cyclical and constrained by rights, capital and customer choice. A strong national brand can still face intense project-level rivalry, so assess each segment and micro-market.'),extraSeed('3','What can stable headline prices hide in a competitive market?','Listed prices in a district have not changed for a year, but developers are offering larger discounts and payment incentives. What should an analyst check?','Effective pricing and the current supply stage, because stable headline prices can hide incentives and slow absorption',['Nothing, because stable listed prices prove healthy demand','Only the number of projects announced','Only the land price paid by each developer'],'Rivalry changes as competing supply, credit and demand move through cycles. Headline price stability can hide incentives and slow absorption, so use effective pricing and the current supply stage.')],'realestate-development-m4-l2':[extraSeed('1','Why should a REIT not be benchmarked directly against a residential merchant developer?','An analyst ranks a listed REIT and a homebuilder on the same profit metric. What does the chapter caution?','They have different mandates, leverage and hold periods, so only matched entities should be benchmarked',['They are identical businesses with the same income profile','A REIT always outperforms a developer','The comparison is valid if both own property'],'Global participants have different mandates, leverage and hold periods. A REIT income profile differs from a residential merchant developer, so benchmark matched entities.'),extraSeed('2','Do company announcements establish the market share of a Vietnam developer?','A developer press release claims a large share of new supply. What should a reviewer do?','Verify project status and entity scope, because announcements do not establish market share or completed capacity',['Accept the claim because companies must report accurately','Treat announced projects as completed supply','Use the claim as an official market statistic'],'Vietnam participants specialize by asset, city, capital and lifecycle role. Company announcements do not establish market share or completed capacity, so verify project status and entity scope.')],'realestate-development-m4-l3':[extraSeed('1','Why can a large land bank be worth less than a smaller one?','Developer A holds a vast unapproved land bank; developer B holds a smaller site that is ready to build. How should they be compared?','By legal readiness, planning, infrastructure and phasing, because a large unapproved land bank may be less valuable than a smaller ready project',['By land area alone, because size measures future value','By the purchase price of the land alone','By the number of projects announced'],'Land area alone is not a comparable measure of future value. A large unapproved land bank may be less valuable than a smaller ready project, so separate announced, controlled and approved pipeline.'),extraSeed('3','Are appraisal gains the same as operating cash?','A developer reports a large profit driven by property revaluations. How should an investor treat it?','Appraisal gains are not operating cash, so group and project figures should be matched on a consistent basis',['Appraisal gains are cash available for dividends','Revaluations always reflect sales already completed','Appraisal gains remove the need for liquidity planning'],'Financial benchmarks need consistent accounting, valuation and financing bases. Appraisal gains are not operating cash, so avoid unmatched group and project figures.')],'realestate-development-m4-l4':[extraSeed('1','How can an option agreement help in land acquisition?','A developer likes a site but its planning path is not yet confirmed. What approach does the chapter describe?','An option agreement can limit early exposure while due diligence proceeds',['Buy the land outright before any diligence','Start construction to secure the planning path','Avoid all sites without existing approvals'],'Verified developable rights are the first success condition. Option agreements can limit early exposure while diligence proceeds, supported by qualified legal review.'),extraSeed('2','Can premium finishes rescue a project with the wrong unit mix?','A project with oversized units is selling slowly, and marketing proposes upgrading finishes. What does the chapter suggest?','No: premium finishes do not fix the wrong unit mix, so buyer and tenant evidence must be tracked',['Yes: better finishes always accelerate sales','Yes: finishes matter more than affordability','No: the project should stop marketing altogether'],'Projects win when product, affordability and execution match demand. Premium finishes do not fix the wrong unit mix, so track buyer and tenant evidence.')],'realestate-development-m4-l5':[extraSeed('1','Why should developers maintain a funding runway even for completed assets?','A completed office building struggles to find a buyer during a period of weak market liquidity. What does the chapter highlight?','A completed asset can still be hard to sell during weak liquidity, so a funding runway should be maintained',['Completed assets always sell quickly at full value','Liquidity risk ends once construction is complete','Illiquidity only affects undeveloped land'],'Property can serve durable needs but ties capital to long, uncertain cycles. A completed asset can still be hard to sell during weak liquidity, so maintain funding runway.'),extraSeed('3','What risk does diversification without capability create for a developer?','A residential developer expands rapidly into hotels, logistics and offices with no experienced teams. What does the chapter warn?','Diversification without capability can dilute controls, so capital should be allocated against risk-adjusted cash flow',['Diversification always reduces risk regardless of capability','New segments need no specialist teams','Expansion improves controls automatically'],'Strategy is the selection of assets, timing, partners and capital exposure. Diversification without capability can dilute controls, so allocate against risk-adjusted cash flow.')],'realestate-development-m5-l1':[extraSeed('1','What do smaller apartment units do for housing affordability?','A developer shrinks unit sizes to lower the ticket price. Which statement is accurate?','Smaller units can improve ticket affordability without guaranteeing value, so household and project evidence is needed',['Smaller units always increase value per square metre','Smaller units guarantee faster absorption in every market','Unit size has no effect on affordability'],'Demand converts into absorption only when product and funding fit households. Smaller units can improve ticket affordability without guaranteeing value, so use household and project evidence.'),extraSeed('3','Does e-commerce growth justify building a warehouse in any location?','An investor plans a speculative warehouse far from transport nodes, citing national e-commerce growth. What does the chapter advise?','No: node, tenant and transport evidence must match, because e-commerce growth does not justify every warehouse location',['Yes: e-commerce growth guarantees demand for every warehouse','Yes: location is irrelevant for logistics property','No: logistics property is never a viable investment'],'Space demand shifts with production, trade and consumption networks. E-commerce growth does not justify every warehouse location, so match node, tenant and transport evidence.')],'realestate-development-m5-l2':[extraSeed('1','What can a BIM model not fix on its own?','A design team builds a detailed BIM model from an outdated site survey. What does the chapter warn?','A BIM model does not resolve inaccurate site or rights data, so model purpose and ownership must be defined',['BIM corrects site survey errors automatically','BIM replaces the need for rights verification','BIM models are only useful after construction'],'Digital tools improve decisions when data and workflows are governed. A BIM model does not resolve inaccurate site or rights data, so define model purpose and ownership.'),extraSeed('2','Can drone progress images replace certified completion checks?','A project manager proposes using drone photos instead of formal progress certification. Which statement is accurate?','No: progress images do not replace certified completion and quality checks',['Yes: images are equivalent to certified completion','Yes: quality checks are unnecessary once drones are used','No: drones have no role in construction monitoring'],'Technology can improve productivity and visibility but requires process change. Progress images do not replace certified completion and quality checks, so validate economics and skills.')],'realestate-development-m5-l3':[extraSeed('1','How should planned infrastructure be treated in a development valuation?','A valuation adds a premium for a metro line that has only been announced. What does the chapter advise?','An announcement should not be capitalized as completed access, so delay and demand should be scenario-tested',['Capitalize the full benefit as soon as a line is announced','Ignore infrastructure entirely in valuation','Assume every announced project opens on schedule'],'Infrastructure can reshape accessibility, but timing and delivered connectivity matter. An announcement should not be capitalized as completed access, so scenario-test delay and demand.'),extraSeed('3','Are online property leads the same as contracted sales?','A digital campaign generates thousands of enquiries through portals and virtual tours. How should the sales team report them?','Online leads are not contracted sales, so data should be protected and authority documented',['Each online lead counts as a signed sale','Online leads replace the need for due diligence','Online leads guarantee investor funding'],'Digital channels increase reach but do not replace diligence or physical delivery. Online leads are not contracted sales, so protect data and document authority.')],'realestate-development-m5-l5':[extraSeed('2','Why can a data center not be planned like a warehouse?','An industrial developer proposes converting a warehouse design into a data center with minor changes. What does the chapter caution?','A data center has different power and operating requirements from a warehouse, so infrastructure and demand must be validated',['Data centers and warehouses share identical requirements','Power supply is irrelevant to data center feasibility','Any logistics site can host a data center without study'],'Manufacturing and services can support specialized property opportunities. A data center has different power and operating requirements from a warehouse, so validate infrastructure and demand.'),extraSeed('3','Why is a positive base-case IRR not enough to approve a project?','A project shows an attractive IRR under base-case assumptions. What should the investment committee test?','Downside scenarios, because a positive base-case IRR can fail under slower absorption and higher interest',['Nothing more, because a positive IRR proves the project is safe','Only the upside case, because downside risk is unlikely','Only the land price, because IRR already captures all risks'],'Future returns depend on disciplined assumptions and optionality. A positive base-case IRR can fail under slower absorption and higher interest, so use decision gates and liquidity buffers.')],'realestate-development-m5-l4':[extraSeed('2','According to the Green Buildings and Resource Efficiency chapter, how should modeled savings be treated?','A project brochure claims large energy savings from design modeling. What should a buyer or lender look for?','Treat modeled savings as unverified until a defined baseline, commissioning and operating evidence support them',['Report predicted savings as achieved results once construction is complete','Accept a green label as proof of efficiency without a baseline or operating data','Skip the baseline when the design uses efficient envelopes and systems'],'Green performance requires a defined baseline, design, commissioning and operating evidence. Modeled savings are not verified operating results, so certification and project scope should be stated.'),extraSeed('3','Across which parts of a development does physical climate risk matter, according to the Climate Risk and Resilient Development chapter?','A lender reviews a project in a flood-prone area. Which statement describes how climate risk should be considered?','Physical climate risk affects site, design, operation, finance and exit',['Climate risk is limited to the construction phase and ends at handover','Climate risk affects insurance cost only and does not influence design, finance or exit','Climate risk is a national issue that site-level assessment cannot change'],'Physical climate risk affects site, design, operation, finance and exit. Risk assessment informs elevation, drainage, envelope, backup systems and emergency planning, using site-specific hazards and current rules.')],'realestate-development-m2-l2':[extraSeed('1','According to the Upstream Activities lesson, what drives the value of a land site?','Two plots sit in the same district, but only one has clear developable rights and manageable obligations. How should a developer compare their land value?','Land value depends on developable rights, obligations and achievable use, not location alone',['Land value is set by location alone, so rights and obligations can be reviewed after purchase','The lowest land price is always the best acquisition because the saving flows straight to profit','Land value is the asking price per square metre regardless of use or obligations'],'Site sourcing and acquisition evaluate rights, planning, access, infrastructure, constraints and transaction structure. Land value depends on developable rights, obligations and achievable use, not location alone.'),extraSeed('3','What should a development concept answer, according to the Market Study and Concept Development chapter?','A developer is choosing unit mix, amenities and positioning for a new project. Which principle should guide the concept?','Concept design should answer demonstrated customer demand and affordability',['Concept design should follow the highest specification the site can physically support','Concept design should copy the product mix of the most expensive nearby project','Concept design can be settled first and tested against customers only after launch'],'Research defines segment, customer, unit mix, amenities, positioning, price or rent and expected sales or lease-up, so the concept answers demonstrated customer demand and affordability.'),extraSeed('1','Why can a low land price be misleading in site acquisition?','A plot is priced far below its neighbours. Which statement best captures the concern the team should test before treating it as a bargain?','A low land price can hide remediation or access cost that changes the true cost of the site',['A low land price shows the site carries less risk than comparable plots','Remediation and access cost can be priced after construction starts without affecting feasibility','Location alone will offset any extra site cost hidden behind a low price'],'A low land price can hide remediation or access cost. Acquisition review should test rights, planning, access, infrastructure and constraints, and use project-specific legal due diligence.'),extraSeed('3','Which statement about market-study evidence matches the Market Study and Concept Development chapter?','A team plans an affordable-housing scheme but only has data on luxury apartments nearby. What is the right conclusion?','Evidence must match the target segment, so luxury supply data cannot justify affordable-housing demand',['Any recent supply data in the district is valid evidence for every housing segment','Strong luxury sales prove that buyers will also pay for affordable units in the same location','Segment-specific evidence matters for pricing but not for unit mix or positioning'],'Concept design should answer demonstrated customer demand and affordability. Luxury supply data cannot justify affordable-housing demand, so use location- and segment-specific evidence.')]};
function quiz(prefix:string,topics:string[],chapterCount:number){if(prefix==='realestate-development-m3-l4')return f2Quiz(prefix,[calculationSeed('1','A HYPOTHETICAL project has GDV USD90m and total development cost USD70m. What are development profit and margin on GDV?','Subtract cost and divide profit by GDV.','USD20m and 22.2%',['USD20m and 28.6%','USD70m and 77.8%','USD90m and 22.2%']),calculationSeed('1','If 100 units are released and 60 are sold in the period, what is sales absorption?','Divide sales by released available units.','60%',['40%','100%','166.7%']),calculationSeed('2','Cash flows are -20 now, -30 in year 1, -20 in year 2 and +90 in year 3. At 10%, what is approximate NPV?','Discount each future cash flow.','USD3.8m',['USD20m','USD0m','-USD3.8m']),calculationSeed('3','Debt is USD42m, cost USD70m and value USD90m. What are LTC and LTV?','Divide debt by cost and value respectively.','60.0% and 46.7%',['46.7% and 60.0%','60.0% and 60.0%','42.0% and 70.0%']),calculationSeed('3','NOI or defined cash available for debt service is USD12m and scheduled debt service is USD8m. What is DSCR?','Divide available income by debt service.','1.50x',['0.67x','1.20x','2.00x'])]);return f2Quiz(prefix,[...topics.slice(0,5).map((topic,i)=>seed(String(i%chapterCount+1),`What is central to ${topic}?`,`A team evaluates ${topic}. What should guide it?`,'Defined property, location, rights, lifecycle stage, customer, capital, cash flow and evidence')),...(EXTRA_SEEDS[prefix]??[])])}export function buildDevelopmentModule(module:number,lessons:DevelopmentLesson[],topics:string[][],next:string[],theme:string){const standardized=standardizeDevelopmentLessons(module,lessons);let visualIndex=0;const decks:Record<string,ReDevelopmentCardData[]>={};const quizzes:Record<string,FashionM2Question[]>={};const takeaways:Record<string,FashionM2Takeaways>={};standardized.forEach(([lesson,items],i)=>{decks[lesson]=items.map(item=>chapter(module,lesson,item,++visualIndex));quizzes[lesson]=quiz(`realestate-development-m${module}-l${i+1}`,topics[i],items.length);takeaways[lesson]={learned:`You can explain ${lesson.toLowerCase()} across Property Development and Investment.`,keyTakeaways:[`Apply ${theme} to a defined asset class, location, customer and lifecycle stage.`,`Separate development sales, recurring rental income, asset value, cash receipts and profit.`,`Rights, planning, demand, capital, delivery, occupancy and timing jointly shape returns.`,`Vietnam opportunities require legal readiness, financing resilience, execution discipline and segment-specific evidence.`,`Use sources with explicit property type, location, period, metric and uncertainty.`],businessImplications:'Build development and investment decisions around verified rights, realistic demand, complete cost and financing assumptions, delivery controls, operating scenarios and exit discipline.',remember:'Property value is created across the lifecycle; market appreciation cannot compensate reliably for weak legal readiness, poor product-market fit or fragile financing.',nextLesson:next[i]??''}});return{decks,quizzes,takeaways}}export function buildDevelopmentVisuals(module:number,lessons:DevelopmentLesson[]){const standardized=standardizeDevelopmentLessons(module,lessons);const specs:Record<string,VisualSpec>={};let index=0;standardized.forEach(([,items])=>items.forEach(item=>{const key=`realestate-development-m${module}-${++index}`;specs[key]=DEVELOPMENT_CHAPTER_VISUALS[key]?.spec??{layout:'taxonomy',title:item.title,kicker:'',root:item.title,rootDetail:'Factors considered together, not in sequence',groups:item.dimensions.map(label=>({label,detail:definitions[label]})),takeaway:item.insight}}));return specs}export function renderDevelopmentVisual(specs:Record<string,VisualSpec>,kind:ReDevelopmentVisualKind){const spec=specs[kind];return spec?<VisualView spec={spec}/>:null}
